        "code": "\"use client\"\n\nimport { useState } from \"react\"\n\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\nimport { PasswordRequirements } from \"@/components/openlmis/password-requirements/password-requirements\"\nimport type { PasswordOwner } from \"@/components/openlmis/password-requirements/password-rules\"\n\nconst OWNER: PasswordOwner = {\n  username: \"divo1\",\n  firstName: \"Grace\",\n  lastName: \"Banda\",\n}\n\nexport default function Page() {\n  // Part met, so both states of a rule show.\n  const [password, setPassword] = useState(\"Stock2\")\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col gap-3 p-8\">\n      <div className=\"flex flex-col gap-1\">\n        <Label htmlFor=\"password\">New Password</Label>\n        <Input\n          aria-describedby=\"password-requirements\"\n          id=\"password\"\n          onChange={(event) => setPassword(event.target.value)}\n          type=\"text\"\n          value={password}\n        />\n      </div>\n      <PasswordRequirements\n        id=\"password-requirements\"\n        owner={OWNER}\n        password={password}\n      />\n    </div>\n  )\n}",
