    "files": [
      {
        "type": "page",
        "name": "page.tsx",
        "code": "\"use client\"\n\nimport { useState } from \"react\"\n\nimport {\n  WorkspaceTabs,\n  WorkspaceTabsContent,\n  WorkspaceTabsList,\n  WorkspaceTabsTrigger,\n} from \"@/components/openlmis/workspace-tabs\"\n\nconst SECTIONS = [\n  {\n    value: \"general\",\n    label: \"General\",\n    body: \"Code, name and dispensing unit.\",\n  },\n  {\n    value: \"programs\",\n    label: \"Programs\",\n    body: \"Programs that supply this product.\",\n  },\n  {\n    value: \"facility-types\",\n    label: \"Facility Types\",\n    body: \"Stock targets for each facility type.\",\n  },\n  {\n    value: \"kit-unpack-list\",\n    label: \"Kit Unpack List\",\n    body: \"Products a kit unpacks into.\",\n  },\n]\n\nexport default function Page() {\n  const [section, setSection] = useState(\"general\")\n  const [narrowSection, setNarrowSection] = useState(\"programs\")\n\n  return (\n    <div className=\"flex w-full max-w-3xl flex-col gap-8 p-8\">\n      <WorkspaceTabs onValueChange={setSection} value={section}>\n        <WorkspaceTabsList label=\"Product Sections\">\n          {SECTIONS.map((item) => (\n            <WorkspaceTabsTrigger key={item.value} value={item.value}>\n              {item.label}\n            </WorkspaceTabsTrigger>\n          ))}\n        </WorkspaceTabsList>\n        {SECTIONS.map((item) => (\n          <WorkspaceTabsContent key={item.value} value={item.value}>\n            <div className=\"flex h-24 items-center justify-center rounded-xl border border-dashed text-sm text-muted-foreground\">\n              {item.body}\n            </div>\n          </WorkspaceTabsContent>\n        ))}\n      </WorkspaceTabs>\n      {/* In a narrow column, two by two. */}\n      <div className=\"w-full max-w-xs\">\n        <WorkspaceTabs onValueChange={setNarrowSection} value={narrowSection}>\n          <WorkspaceTabsList label=\"Product Sections, Narrow\" wrap=\"grid\">\n            {SECTIONS.map((item) => (\n              <WorkspaceTabsTrigger key={item.value} value={item.value}>\n                {item.label}\n              </WorkspaceTabsTrigger>\n            ))}\n          </WorkspaceTabsList>\n        </WorkspaceTabs>\n      </div>\n    </div>\n  )\n}",
        "lang": "tsx",
        "target": null
      },
      {
        "type": "component",
        "name": "workspace-tabs.tsx",
        "code": "\"use client\"\n\nimport type { ReactNode } from \"react\"\n\nimport { Tabs, TabsContent, TabsList, TabsTrigger } from \"@/components/ui/tabs\"\nimport { cn } from \"@/lib/utils\"\n\ntype WorkspaceTabsProps = {\n  value: string\n  onValueChange: (value: string) => void\n  children: ReactNode\n}\n\n/** Tabs that split one page, e.g. a product's General, Programs and Facility Types. */\nexport function WorkspaceTabs({\n  value,\n  onValueChange,\n  children,\n}: WorkspaceTabsProps) {\n  return (\n    <Tabs\n      className=\"gap-4\"\n      onValueChange={(next) => onValueChange(String(next))}\n      value={value}\n    >\n      {children}\n    </Tabs>\n  )\n}\n\ntype WorkspaceTabsListProps = {\n  /** Names the tab list for screen readers, e.g. \"Product Sections\". */\n  label: string\n  /** Narrow: one tab per row, or two by two with `grid`; then a single row once there is room. */\n  wrap?: \"column\" | \"grid\"\n  children: ReactNode\n}\n\nexport function WorkspaceTabsList({\n  label,\n  wrap = \"column\",\n  children,\n}: WorkspaceTabsListProps) {\n  return (\n    // Its own container, so the tabs wrap by the room the page gives them, not the window.\n    <div className=\"@container\">\n      <TabsList\n        aria-label={label}\n        className={cn(\n          \"grid w-full group-data-horizontal/tabs:h-auto @lg:inline-flex @lg:w-fit @lg:group-data-horizontal/tabs:h-8\",\n          wrap === \"grid\" ? \"grid-cols-2\" : \"grid-cols-1\"\n        )}\n      >\n        {children}\n      </TabsList>\n    </div>\n  )\n}\n\nexport function WorkspaceTabsTrigger({\n  value,\n  children,\n}: {\n  value: string\n  children: ReactNode\n}) {\n  return <TabsTrigger value={value}>{children}</TabsTrigger>\n}\n\nexport function WorkspaceTabsContent({\n  value,\n  children,\n}: {\n  value: string\n  children: ReactNode\n}) {\n  return <TabsContent value={value}>{children}</TabsContent>\n}",
        "lang": "tsx",
        "target": "components/openlmis/workspace-tabs.tsx"
      }
    ]
